import { Component, Input } from '@angular/core';

@Component({
  standalone: true,
  selector: 'wgj-button',
  templateUrl: './button.component.html',
  styleUrls: ['./button.component.scss'],
})
export class ButtonComponent {
  @Input() link = '';
}
<a class="button" rel="noreferrer" target="_blank" [href]="link">
  <span class="button__label"> <ng-content></ng-content> </span>
  <img src="assets/img/registration-btn.png" alt="fondo pixelado del botón" />
</a>
